-- Admin dashboard reads of auth.session: listSignIns orders by created_at,
-- activityAt filters on expires_at. Custom migration because auth/.../schema.ts
-- is regenerated by `bun run auth:schema` and would lose a hand-added index.
CREATE INDEX "session_createdAt_idx" ON "auth"."session" USING btree ("created_at");--> statement-breakpoint
CREATE INDEX "session_expiresAt_idx" ON "auth"."session" USING btree ("expires_at");
